('bk_ara15','arabic','mcq','نقرأ ونفهم ١','i_book',array['g1','g2']::text[],'اللغة العربية','فهم نص قصير','mid','نصوص قصيرة وأسئلة بسيطة.','اقرأ النص ثم اختر الجواب.',$j${"qs": [{"q": "قرأ سالم قصة عن أرنب صغير يحب الجزر. ماذا يحب الأرنب؟", "o": ["الجزر", "الحليب", "العشب الجاف"], "why": "الأرنب يحب الجزر.", "img": "1f430"}, {"q": "ذهبت مريم إلى الحديقة مع أمها، ولعبت بالكرة. مع من ذهبت مريم؟", "o": ["مع أمها", "مع أبيها", "وحدها"], "why": "ذهبت مريم مع أمها."}, {"q": "في الصباح شرب علي الحليب وأكل الخبز. ماذا شرب علي؟", "o": ["الحليب", "الماء", "العصير"], "why": "شرب علي الحليب.", "img": "1f37c"}, {"q": "زرعت ليلى بذرة وسقتها كل يوم فنمت. ماذا فعلت ليلى بالبذرة؟", "o": ["سقتها كل يوم", "رمتها", "أكلتها"], "why": "سقتها ليلى كل يوم فنمت.", "img": "1f331"}]}$j$::jsonb,null,null,null,$j${"href": "summaries/", "label": "الملخصات والمراجعات"}$j$::jsonb,'نشاط أصلي من إنتاج زاد: فُحصت الإجابات والبنية آليا وحُلّ كل نشاط آليا في الاختبار، ولم يراجعه مختص لغوي أو تربوي بعد.',true,'published',15),
('bk_ara16','arabic','mcq','نقرأ ونفهم ٢','i_book',array['g3','g4']::text[],'اللغة العربية','فهم نص والاستنتاج منه','adv','نصوص أطول مع أسئلة فهم واستنتاج.','اقرأ النص ثم اختر الجواب.',$j${"qs": [{"q": "يسكن الجمل في الصحراء، ويصبر على العطش أياما لأنه يخزن الطعام في سنامه. لماذا يصبر الجمل على العطش؟", "o": ["لأنه يخزن الطعام في سنامه", "لأنه يشرب كثيرا كل يوم", "لأنه يسكن البحر"], "why": "ذكر النص أن السنام يخزن الطعام.", "img": "1f42a"}, {"q": "جمعت نور أوراق الشجر في الخريف، ولصقتها في دفترها لتصنع لوحة جميلة. ماذا صنعت نور؟", "o": ["لوحة من أوراق الشجر", "كتابا عن الحيوانات", "قصة عن الخريف"], "why": "صنعت نور لوحة من أوراق الشجر.", "img": "x_leaf"}, {"q": "أخذ خالد مظلته معه لأن السماء ملبدة بالغيوم. ماذا نستنتج؟", "o": ["أن المطر قد ينزل", "أن الجو حار جدا", "أن الليل قد جاء"], "why": "الغيوم الكثيفة تدل على احتمال المطر.", "img": "x_umbrella"}, {"q": "اجتهد الطلاب في المراجعة قبل الاختبار فنجحوا جميعا. ما سبب نجاحهم؟", "o": ["اجتهادهم في المراجعة", "كثرة النوم", "قلة الدراسة"], "why": "سبب نجاحهم اجتهادهم في المراجعة."}]}$j$::jsonb,null,null,null,$j${"href": "summaries/", "label": "الملخصات والمراجعات"}$j$::jsonb,'نشاط أصلي من إنتاج زاد: فُحصت الإجابات والبنية آليا وحُلّ كل نشاط آليا في الاختبار، ولم يراجعه مختص لغوي أو تربوي بعد.',true,'published',16),
